  const pw = pop.offsetWidth || fallbackW, ph = pop.offsetHeight || fallbackH;
  let left = rect.left - rootRect.left + rect.width / 2 - pw / 2;
  let top = rect.top - rootRect.top - ph - 10;
  if (top < 4) top = rect.bottom - rootRect.top + 10;
